// app/api/stats/route.js
import { NextResponse } from "next/server";
import connectDB from "@/lib/db";
import Question from "@/models/Question";
import Answer from "@/models/Answer";   // NEW
import AIModel from "@/models/AIModel"; // NEW

function startOfDay(d){ const x=new Date(d); x.setHours(0,0,0,0); return x; }
function addDays(d,n){ const x=new Date(d); x.setDate(x.getDate()+n); return x; }
function iso(d){ return d.toISOString().slice(0,10); }
function parseRange(r){ return r==="14d"?14 : r==="30d"?30 : 7; }

export async function GET(req){
  try{
    await connectDB();
    const url = new URL(req.url);
    const range = url.searchParams.get("range");
    const days = parseRange(range);

    const today = startOfDay(new Date());
    const from  = addDays(today, -(days-1));

    // --- totals (questions) ---
    const [totalQuestions, todayNew] = await Promise.all([
      Question.countDocuments({}),
      Question.countDocuments({ createDate: { $gte: today } })
    ]);

    // --- daily (questions by day) ---
    const dailyAgg = await Question.aggregate([
      { $match: { createDate: { $gte: from, $lt: addDays(today,1) } } },
      { $group: {
          _id: { $dateToString: { format: "%Y-%m-%d", date: "$createDate" } },
          count: { $sum: 1 }
        }
      },
      { $sort: { _id: 1 } },
    ]);
    const qMap = new Map(dailyAgg.map(r => [r._id, r.count]));
    const daily = Array.from({length: days}, (_,i)=>{
      const d = addDays(from,i); const k = iso(d);
      return { date: k, questions: qMap.get(k) ?? 0 };
    });

    // --- byModel (pie): đếm câu trả lời theo AI ---
    // answers.authorModel -> lookup sang AIModel để lấy displayName/modelId
    const byModel = await Answer.aggregate([
      { $group: { _id: "$authorModel", count: { $sum: 1 } } },
      { $lookup: {
          from: "aimodels",              // tên collection của AIModel
          localField: "_id",
          foreignField: "_id",
          as: "model"
        }
      },
      { $unwind: { path: "$model", preserveNullAndEmptyArrays: true } },
      { $project: {
          _id: 0,
          count: 1,
          // ưu tiên displayName, fallback modelId, cuối cùng là ObjectId
          name: { $ifNull: [ "$model.displayName", { $ifNull: ["$model.modelId", { $toString: "$_id" }] } ] }
        }
      },
      { $sort: { count: -1 } }
    ]);

    return NextResponse.json({
      totals: { questions: totalQuestions, todayNew },
      daily,
      byModel,         // <-- thêm field này cho PieChart
    });
  }catch(err){
    console.error("GET /api/stats error:", err);
    return NextResponse.json({ error: String(err?.message||err) }, { status: 500 });
  }
}
